<?php
namespace App\Actions;use App\Models\ServiceRequest;use Illuminate\Support\Facades\DB;use Illuminate\Validation\ValidationException;
class TransitionServiceRequestAction{private const MAP=['PENDING'=>['ACCEPTED','REJECTED','CANCELLED'],'ACCEPTED'=>['ASSIGNED','IN_PROGRESS','CANCELLED'],'ASSIGNED'=>['IN_PROGRESS','CANCELLED'],'IN_PROGRESS'=>['COMPLETED','ESCALATED','CANCELLED'],'ESCALATED'=>['ASSIGNED','IN_PROGRESS','COMPLETED'],'COMPLETED'=>[],'REJECTED'=>[],'CANCELLED'=>[]];public function execute(ServiceRequest $r,string $to,?int $userId=null,?string $note=null):ServiceRequest{return DB::transaction(function()use($r,$to,$userId,$note){$r->refresh();$from=$r->status;if(!in_array($to,self::MAP[$from]??[],true))throw ValidationException::withMessages(['status'=>"Invalid transition {$from} → {$to}."]);$changes=['status'=>$to];if($to==='ACCEPTED')$changes['accepted_at']=now();if($to==='COMPLETED')$changes['completed_at']=now();$r->update($changes);DB::table('service_request_status_history')->insert(['hotel_id'=>$r->hotel_id,'service_request_id'=>$r->id,'changed_by'=>$userId,'from_status'=>$from,'to_status'=>$to,'note'=>$note,'created_at'=>now()]);return $r->fresh();});}}
